:"period drama film","d":"film and television genre","labels":[["period drama film","period drama film","en","preferred"],["costume drama film","costume drama film","en","alternate"],["コスチューム・プレイ","コスチューム プレイ","ja","alternate"],["코스튬 드라마","코스튬 드라마","ko","alternate"],["古裝劇","古裝劇","zh","alternate"],["古装剧","古装剧","zh","alternate"]],"parent":"medium:screen_genres","qid":"Q542475","sitelinks":16,"slice":"screen_genres_deep"},{"k":"genre:heroic_bloodshed","kind":"genre","l":"heroic bloodshed","d":"film genre","labels":[["heroic bloodshed","heroic bloodshed","en","preferred"],["英雄的な流血","英雄的な流血","ja","alternate"],["홍콩 누아르","홍콩 누아르","ko","alternate"],["英雄式血灑","英雄式血灑","zh","alternate"]],"parent":"medium:screen_genres","qid":"Q622310","sitelinks":16,"slice":"screen_genres_deep"},{"k":"genre:taiga_drama","kind":"genre","l":"taiga drama","d":"Japanese term coined by NHK for year-long historical drama television series","labels":[["taiga drama","taiga drama","en","preferred"],["long-lasting historical drama","long lasting historical drama","en","alternate"],["大河ドラマ","大河ドラマ","ja","alternate"],["大河劇","大河劇","ja","alternate"],["NHK大河ドラマ","nhk大河ドラマ","ja","alternate"],["NHK 대하드라마","nhk 대하드라마","ko","alternate"]],"parent":"medium:screen_genres","qid":"Q1200935","sitelinks":15,"slice":"screen_genres_deep"},{"k":"genre:auteur_film","kind":"genre","l":"auteur film","d":"film genre","labels":[["auteur film","auteur film","en","preferred"],["작가주의 영화","작가주의 영화","ko","alternate"]],"parent":"medium:screen_genres","qid":"Q13209138","sitelinks":15,"slice":"screen_genres_deep"},{"k":"genre:free_cinema","kind":"genre","l":"Free Cinema","d":"British documentary film movement","labels":[["Free Cinema","free cinema","en","preferred"],["フリー・シネマ","フリー シネマ","ja","alternate"],["フリーシネマ","フリーシネマ","ja","alternate"],["자유영화","자유영화","ko","alternate"],["프리 시네마","프리 시네마","ko","alternate"],["자유 영화","자유 영화","ko","alternate"]],"parent":"medium:screen_genres","qid":"Q1352102","sitelinks":15,"slice":"screen_genres_deep"},{"k":"genre:nature_documentary","kind":"genre","l":"nature documentary","d":"film and television genre","labels":[["nature documentary","nature documentary","en","preferred"],["natural history film","natural history film","en","alternate"],["wildlife film","wildlife film","en","alternate"],["wildlife documentary","wildlife documentary","en","alternate"],["nature show","nature show","en","alternate"],["自然ドキュメンタリー","自然ドキュメンタリー","ja","alternate"]],"parent":"medium:screen_genres","qid":"Q1760864","sitelinks":15,"slice":"screen_genres_deep"},{"k":"genre:legal_thriller","kind":"genre","l":"legal thriller","d":"fiction genre","labels":[["legal thriller","legal thriller","en","preferred"],["法廷もの","法廷もの","ja","alternate"],["法廷劇","法廷劇","ja","alternate"],["법정 스릴러","법정 스릴러","ko","alternate"],["法律驚慄","法律驚慄","zh","alternate"]],"parent":"medium:screen_genres","qid":"Q2490520","sitelinks":15,"slice":"screen_genres_deep"},{"k":"genre:detective_film","kind":"genre","l":"detective film","d":"film genre","labels":[["detective film","detective film","en","preferred"],["추리 영화","추리 영화","ko","alternate"]],"parent":"medium:screen_genres","qid":"Q25533274","sitelinks":15,"slice":"screen_genres_deep"},{"k":"genre:slow_television","kind":"genre","l":"slow television","d":"television genre featuring a very long television coverage of an ordinary event in its complete length","labels":[["slow television","slow television","en","preferred"],["slow TV","slow tv","en","alternate"],["スローテレビ","スローテレビ","ja","alternate"],["慢电视","慢电视","zh","alternate"]],"parent":"medium:screen_genres","qid":"Q3377903","sitelinks":15,"slice":"screen_genres_deep"},{"k":"genre:kitchen_sink_realism","kind":"genre","l":"kitchen sink realism","d":"British social realist artistic movement","labels":[["kitchen sink realism","kitchen sink realism","en","preferred"],["kitchen sink drama","kitchen sink drama","en","alternate"],["Kitchen Sink School","kitchen sink school","en","alternate"],["キッチンシンク・リアリズム","キッチンシンク リアリズム","ja","a